<script setup lang="ts">
import { computed,ref } from 'vue'
import { CheckCircle2,Minus,Plus,RotateCcw,Trash2,X } from 'lucide-vue-next'
import { optionText,type PresentationBlock,type PresentationLayout,type Question } from '../api'
import AuthenticatedImage from './AuthenticatedImage.vue'
import MathPreview from './MathPreview.vue'

const props=defineProps<{question:Question;saving?:boolean}>()
const emit=defineEmits<{(event:'close'):void;(event:'save',layout:PresentationLayout):void}>()
const zoom=ref(0.85)
function defaults():PresentationLayout{const blocks:PresentationBlock[]=[{id:'stem',kind:'stem',x:4,y:4,width:92,height:18},{id:'options',kind:'options',x:4,y:24,width:92,height:14}];(props.question.figureUrls||[]).forEach((_,index)=>blocks.push({id:`figure-${index}`,kind:'figure',figureIndex:index,x:5+(index%3)*31,y:42+Math.floor(index/3)*34,width:28,height:30}));return{width:1000,height:620,blocks}}
const layout=ref<PresentationLayout>(props.question.presentationLayout?.blocks?.length?JSON.parse(JSON.stringify(props.question.presentationLayout)):defaults())
if((layout.value.width||0)<320)layout.value.width=1000
const blocks=computed(()=>layout.value.blocks||[])
let active:null|{id:string;mode:'move'|'resize';x:number;y:number;start:PresentationBlock;bounds:DOMRect}=null
let canvasActive:null|{mode:'width'|'height'|'both';x:number;y:number;width:number;height:number}=null
function begin(event:PointerEvent,block:PresentationBlock,mode:'move'|'resize'){event.preventDefault();event.stopPropagation();const canvas=(event.currentTarget as HTMLElement).closest<HTMLElement>('.free-layout-canvas');if(!canvas)return;active={id:block.id,mode,x:event.clientX,y:event.clientY,start:{...block},bounds:canvas.getBoundingClientRect()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',end,{once:true})}
function move(event:PointerEvent){if(!active)return;const dx=(event.clientX-active.x)/active.bounds.width*100,dy=(event.clientY-active.y)/active.bounds.height*100;layout.value={...layout.value,blocks:blocks.value.map(block=>{if(block.id!==active!.id)return block;const start=active!.start;if(active!.mode==='move')return{...block,x:clamp(start.x+dx,0,100-start.width),y:clamp(start.y+dy,0,100-(start.height||10))};return{...block,width:clamp(start.width+dx,8,100-start.x),height:clamp((start.height||15)+dy,6,100-start.y)}})} }
function end(){active=null;window.removeEventListener('pointermove',move)}
function beginCanvasResize(event:PointerEvent,mode:'width'|'height'|'both'){event.preventDefault();event.stopPropagation();canvasActive={mode,x:event.clientX,y:event.clientY,width:layout.value.width||1000,height:layout.value.height||620};window.addEventListener('pointermove',resizeCanvas);window.addEventListener('pointerup',endCanvasResize,{once:true})}
function resizeCanvas(event:PointerEvent){if(!canvasActive)return;const width=canvasActive.mode==='height'?canvasActive.width:canvasActive.width+(event.clientX-canvasActive.x)/zoom.value,height=canvasActive.mode==='width'?canvasActive.height:canvasActive.height+(event.clientY-canvasActive.y)/zoom.value;changeCanvasSize(width,height)}
function endCanvasResize(){canvasActive=null;window.removeEventListener('pointermove',resizeCanvas)}
function changeCanvasSize(requestedWidth:number,requestedHeight:number){
 const previousWidth=layout.value.width||1000,previousHeight=layout.value.height||620
 const contentRight=Math.max(0,...blocks.value.map(block=>(block.x+block.width)*previousWidth/100)),contentBottom=Math.max(0,...blocks.value.map(block=>(block.y+(block.height||15))*previousHeight/100))
 const nextWidth=Math.max(520,Math.min(1600,Math.round(Math.max(requestedWidth,contentRight+24)))),nextHeight=Math.max(320,Math.min(1600,Math.round(Math.max(requestedHeight,contentBottom+24))))
 if(nextWidth===previousWidth&&nextHeight===previousHeight)return
 const xRatio=previousWidth/nextWidth,yRatio=previousHeight/nextHeight
 layout.value={...layout.value,width:nextWidth,height:nextHeight,blocks:blocks.value.map(block=>({...block,x:block.x*xRatio,y:block.y*yRatio,width:block.width*xRatio,height:(block.height||15)*yRatio}))}
}
function remove(id:string){layout.value={...layout.value,blocks:blocks.value.filter(block=>block.id!==id)}}
function reset(){layout.value=defaults();zoom.value=.85}
function changeHeight(value:number){changeCanvasSize(layout.value.width||1000,value||layout.value.height||620)}
function inputHeight(event:Event){changeHeight(Number((event.target as HTMLInputElement).value))}
function clamp(value:number,min:number,max:number){return Math.round(Math.max(min,Math.min(max,value))*10)/10}
</script>

<template><div class="layout-editor-layer"><div class="layout-editor-dialog"><header><div><h2>编辑试题版式</h2><p>题干、选项和图片都可以自由拖动、缩放或删除</p></div><div class="canvas-height"><label>画板高度</label><button title="减少画板高度" @click="changeHeight((layout.height||620)-80)"><Minus/></button><input type="number" min="320" max="1600" step="20" :value="layout.height||620" @change="inputHeight"/><span>px</span><button title="增加画板高度" @click="changeHeight((layout.height||620)+80)"><Plus/></button></div><div class="canvas-zoom"><button title="缩小" @click="zoom=Math.max(.5,zoom-.1)"><Minus/></button><span>{{Math.round(zoom*100)}}%</span><button title="放大" @click="zoom=Math.min(1.5,zoom+.1)"><Plus/></button><button @click="zoom=1">适应画布</button></div><button class="close-editor" @click="emit('close')"><X/></button></header><main><div class="canvas-scroll"><div class="canvas-zoom-wrapper" :style="{width:`${(layout.width||1000)*zoom}px`,height:`${(layout.height||620)*zoom}px`}"><div class="free-layout-canvas" :style="{width:`${layout.width||1000}px`,height:`${layout.height||620}px`,transform:`scale(${zoom})`}"><div v-for="block in blocks" :key="block.id" class="free-layout-block" :data-kind="block.kind" :style="{left:`${block.x}%`,top:`${block.y}%`,width:`${block.width}%`,height:`${block.height||15}%`}" @pointerdown="begin($event,block,'move')"><div class="block-label">{{block.kind==='stem'?'题干':block.kind==='options'?'选项':`图片 ${(block.figureIndex||0)+1}`}}</div><button class="delete-block" title="删除" @pointerdown.stop @click.stop="remove(block.id)"><Trash2/></button><div class="block-content"><MathPreview v-if="block.kind==='stem'" :text="question.stem"/><div v-else-if="block.kind==='options'" class="canvas-options"><MathPreview v-for="(option,index) in question.options" :key="index" :text="`${String.fromCharCode(65+index)}. ${optionText(option,index)}`"/></div><AuthenticatedImage v-else-if="question.figureUrls?.[block.figureIndex||0]" :path="question.figureUrls[block.figureIndex||0]"/></div><i class="block-resizer" @pointerdown="begin($event,block,'resize')"></i></div><i class="canvas-resizer width" title="拖动调整画板宽度" @pointerdown="beginCanvasResize($event,'width')"></i><i class="canvas-resizer height" title="拖动调整画板高度" @pointerdown="beginCanvasResize($event,'height')"></i><i class="canvas-resizer both" title="拖动调整画板宽高" @pointerdown="beginCanvasResize($event,'both')"></i></div></div></div></main><footer><button class="ghost" @click="reset"><RotateCcw/>恢复默认</button><div><button class="ghost" @click="emit('close')">取消</button><button class="primary" :disabled="saving" @click="emit('save',layout)"><CheckCircle2/>{{saving?'保存中':'保存版式'}}</button></div></footer></div></div></template>

<style scoped>
.layout-editor-layer{position:fixed;inset:0;z-index:100;background:#172033aa;backdrop-filter:blur(5px);display:grid;place-items:center}.layout-editor-dialog{width:min(1300px,96vw);height:min(880px,94vh);background:#fff;border-radius:18px;overflow:hidden;display:grid;grid-template-rows:84px 1fr 66px;box-shadow:0 30px 100px #10182b66}.layout-editor-dialog>header{display:flex;align-items:center;gap:14px;padding:0 22px;border-bottom:1px solid #e4e9f1}.layout-editor-dialog h2,.layout-editor-dialog p{margin:0}.layout-editor-dialog h2{font-size:20px}.layout-editor-dialog p{margin-top:6px;color:#768197;font-size:12px}.canvas-height,.canvas-zoom{display:flex;align-items:center;gap:5px;padding:5px;border:1px solid #e0e6ef;border-radius:10px}.canvas-height{margin-left:auto}.canvas-height label{padding:0 5px;color:#66738a;font-size:12px}.canvas-height input{width:64px;height:30px;border:0;border-left:1px solid #e3e8f0;border-right:1px solid #e3e8f0;padding:0 6px;text-align:right;outline:none}.canvas-height>span{font-size:11px;color:#8792a4}.canvas-height button,.canvas-zoom button,.close-editor{border:0;background:#f4f7fb;border-radius:7px;height:30px;padding:0 9px;color:#536078}.canvas-height svg,.canvas-zoom svg,.close-editor svg{width:16px}.canvas-zoom span{width:48px;text-align:center;font-size:12px}.close-editor{height:36px;width:36px;padding:0}.layout-editor-dialog>main{overflow:hidden;background:#edf1f6;padding:24px}.canvas-scroll{width:100%;height:100%;overflow:auto;display:flex;align-items:flex-start;justify-content:center}.canvas-zoom-wrapper{flex:none;position:relative}.free-layout-canvas{position:absolute;left:0;top:0;transform-origin:top left;background:#fff;box-shadow:0 8px 35px #35425a25;border-radius:10px;overflow:hidden}.free-layout-block{position:absolute;border:1.5px dashed #526ff0;background:#ffffffee;cursor:move;min-width:30px;min-height:28px;line-height:1.5}.free-layout-block:hover{border-style:solid;box-shadow:0 0 0 2px #526ff020}.block-label{position:absolute;left:-1px;bottom:100%;padding:3px 7px;background:#526ff0;color:#fff;font-size:10px;line-height:16px;border-radius:5px 5px 0 0}.delete-block{position:absolute;z-index:3;right:4px;top:4px;width:26px;height:26px;border:0;border-radius:6px;background:#fff0f1;color:#d34955;display:none;place-items:center}.free-layout-block:hover .delete-block{display:grid}.delete-block svg{width:14px}.block-content{width:100%;height:100%;overflow:auto;padding:10px 34px 10px 10px;font-size:15px}.block-content :deep(img){width:100%;height:100%;object-fit:contain}.canvas-options{display:grid;grid-template-columns:repeat(2,1fr);gap:8px 18px}.block-resizer{position:absolute;right:-6px;bottom:-6px;width:13px;height:13px;border:2px solid #fff;border-radius:50%;background:#526ff0;cursor:nwse-resize}.layout-editor-dialog>footer{display:flex;align-items:center;justify-content:space-between;padding:0 22px;border-top:1px solid #e4e9f1}.layout-editor-dialog>footer>div{display:flex;gap:10px}.layout-editor-dialog footer svg{width:16px}
.canvas-resizer{position:absolute;z-index:8;background:#2864eb}.canvas-resizer.width{right:0;top:50%;width:8px;height:56px;border-radius:6px 0 0 6px;transform:translateY(-50%);cursor:ew-resize}.canvas-resizer.height{left:50%;bottom:0;width:56px;height:8px;border-radius:6px 6px 0 0;transform:translateX(-50%);cursor:ns-resize}.canvas-resizer.both{right:0;bottom:0;width:18px;height:18px;border:3px solid #fff;border-radius:50% 0 0 0;cursor:nwse-resize;box-shadow:0 0 0 1px #2864eb}
</style>
